}

.tooltip[x-placement^=right] .tooltip-arrow {
  left: -5px;
  top: calc(50% - var(--rem-size-10));
  margin-left: 0;
  margin-right: 0;
  border-width: var(--rem-size-5) var(--rem-size-5) var(--rem-size-5) 0;
