.idt-page-top {
  display: flex;
  align-items: center;
  position: relative;
  width: 100%;
  min-height: 380px;
  background-color: var(--main-color-darkest);
  overflow: hidden;
}

@media only screen and (max-width: 639px) {
  .idt-page-top {
    flex-flow: column;
  }
}

@media only screen and (max-width: 639px) {
  .idt-page-top--small {
    min-height: auto;
  }
}

@media only screen and (min-width: 640px) {
  .idt-page-top--small {
    min-height: 100px;
  }
}

.idt-page-top__header {
  flex: 1 0 auto;
  width: 100%;
  z-index: 1;
}

.idt-page-top__header .row {
  justify-content: center;
}

.idt-page-top__search {
  margin: 0;
  padding-right: 2.2rem;
  color: var(--white);
  background-color: var(--white-alpha20);
  border: none;
}

.idt-page-top__search::-moz-placeholder {
  color: var(--white);
}

.idt-page-top__search::placeholder {
  color: var(--white);
}

.idt-page-top__search:focus {
  border: none;
  background-color: var(--white-alpha20);
}

.idt-page-top__search__container {
  position: relative;
}

@media only screen and (max-width: 639px) {
  .idt-page-top__search__container {
    flex: 0 0 100%;
    margin-bottom: 1rem;
  }
}

@media only screen and (min-width: 640px)and (max-width: 1023px) {
  .idt-page-top__search__container {
    flex: 0 0 50%;
  }
}

@media only screen and (max-width: 1023px) {
  .idt-page-top__search__container {
    order: 2;
  }
}

@media only screen and (min-width: 1024px) {
  .idt-page-top__search__container {
    flex: 0 0 33%;
  }
}

.idt-page-top__search__container:after {
  content: "";
  display: block;
  position: absolute;
  top: 50%;
  right: 1.5rem;
  color: var(--white);
  font-family: var(--ideacons-font);
  font-size: 1.2rem;
  transform: translateY(-50%);
}

.idt-page-top__title {
  margin: 0;
  color: var(--white);
  font-family: var(--title-font-family);
  font-weight: 300;
  text-align: center;
}

@media only screen and (max-width: 639px) {
  .idt-page-top__title {
    margin-top: .5rem;
    margin-bottom: .5rem;
  }
}

@media only screen and (min-width: 640px)and (max-width: 1023px) {
  .idt-page-top__title {
    font-size: 1.75rem;
  }
}

@media only screen and (max-width: 1023px) {
  .idt-page-top__title {
    margin-bottom: 1rem;
  }
}

@media only screen and (min-width: 1024px) {
  .idt-page-top__title {
    font-size: 2.125rem;
  }
}

@media only screen and (max-width: 1023px) {
  .idt-page-top__title__container {
    flex: 0 0 100%;
    order: 1;
  }
}

.idt-page-top__actions {
  display: flex;
  position: relative;
}

@media only screen and (max-width: 1023px) {
  .idt-page-top__actions {
    order: 3;
  }
}

@media only screen and (min-width: 1024px) {
  .idt-page-top__actions {
    flex: 0 0 33%;
  }
}

.idt-page-top__actions:not(.is-column) {
  align-items: center;
}

@media only screen and (max-width: 639px) {
  .idt-page-top__actions:not(.is-column) {
    justify-content: center;
    margin-bottom: 1rem;
  }
}

@media only screen and (min-width: 640px) {
  .idt-page-top__actions:not(.is-column) {
    justify-content: flex-end;
  }
}

.idt-page-top__actions.is-column {
  flex-flow: column nowrap;
  justify-content: space-between;
  align-items: flex-end;
}

.idt-page-top__actions .switch-view {
  margin: 0;
  padding: .6rem 1.1rem;
  color: var(--main-color-dark);
  background: var(--main-color-lighter);
  border-radius: var(--global-radius);
  font-size: var(--rem-size-14);
  font-weight: 500;
  text-transform: uppercase;
  line-height: 1.4;
  transition: all .3s ease-in-out;
}

.idt-page-top__actions .switch-view span {
  margin: 0 .3rem;
  vertical-align: text-top;
}

.idt-page-top__actions .switch-view:hover {
  color: var(--white);
  background: var(--main-color);
}

.idt-page-top__actions .switch-view *:last-child {
  margin-left: .4rem;
}

.idt-page-top__actions .button {
  margin: 0;
  font-size: .75rem;
  font-weight: 700;
  text-transform: uppercase;
  line-height: 1.4;
}

.idt-page-top__actions .button:not(:last-child) {
  margin-right: .5rem;
}

.idt-page-top__actions .button.has-separator {
  position: relative;
  margin-left: 3rem;
}

.idt-page-top__actions .button.has-separator:after {
  content: "";
  display: block;
  position: absolute;
  top: 50%;
  left: -1.5rem;
  height: 1.5rem;
  border-right: 1px solid var(--grey);
  transform: translate(-50%, -50%);
}

.idt-page-top__actions .link {
  font-size: 1.1rem;
  font-weight: 700;
  white-space: nowrap;
}

.idt-page-top-mobile {
  display: flex;
  align-items: center;
  position: relative;
  width: 100%;
  height: 35px;
  background-color: var(--main-color);
  overflow: hidden;
  z-index: 10;
}

@media only screen and (min-aspect-ratio: 13/9) {
  .idt-page-top-mobile.conference-top {
    display: none;
  }
}

.idt-page-top-mobile .idt-page-top {
  color: #fff;
}

.idt-page-top-mobile .idt-page-top__blur {
  display: none;
}

.idt-page-section {
  display: flex;
  align-items: center;
  min-height: 122px;
}

.idt-page-section__content {
  flex: 1 1 auto;
}

.idt-page-section__content:not(.align-middle) {
  align-items: flex-end;
